SELECT 'courts' AS tbl, COUNT(*)::text AS cnt FROM courts
UNION ALL SELECT 'storage_locations', COUNT(*)::text FROM storage_locations
UNION ALL SELECT 'personnel', COUNT(*)::text FROM personnel
UNION ALL SELECT 'cases', COUNT(*)::text FROM cases
UNION ALL SELECT 'evidence_items', COUNT(*)::text FROM evidence_items
UNION ALL SELECT 'custody_transfers', COUNT(*)::text FROM custody_transfers
UNION ALL SELECT 'lab_tests', COUNT(*)::text FROM lab_tests
UNION ALL SELECT 'evidence_requests', COUNT(*)::text FROM evidence_requests
UNION ALL SELECT 'disclosure_logs', COUNT(*)::text FROM disclosure_logs
UNION ALL SELECT 'ai_summaries', COUNT(*)::text FROM ai_summaries
ORDER BY tbl;